(** * HOL4 L3 RISC-V model [riscv] (generated by L3)

    Port of [HOL/examples/l3-machine-code/riscv/model/riscvScript.sml], which
    is itself generated by L3 through the [Import] library
    ([HOL/examples/l3-machine-code/common/Import.sml]).  This file is
    produced mechanically from the L3 source terms (by a script kept outside
    the repository, which runs the HOL script under a mock [Import] library
    and prints every term with its HOL type); the translation is:

    - [Construct [(t, cs)]] (an algebraic datatype) is an [Inductive];
      [Record (t, fs)] is a Rocq [Record] whose fields carry the names of
      HOL's accessor constants [t_f] (e.g. [riscv_state_c_PC]); a record
      update [Rupd (f, (r, v))] ([r with f := v]) is HOL's field-update
      constant [t_f_fupd (K v) r], written [t_f_fupd (fun _ => v) r].
      HOL type names that are also constructor names ([ArithI], [Branch],
      [Load], ...) get the suffix [_ty]; constructors keep their HOL names.
    - [FTy n] / [F8] ... is [word n]; [PTy (a, b)] is [a * b]: an L3 tuple
      [a # b # c] (a right-nested HOL product) is the Rocq tuple [a * b * c]
      (left-nested), written and matched as [(x, y, z)].  Projections and
      partial tuple patterns ([FST], [SND], [(x, rest)]) are translated
      through this correspondence (by destructuring the whole tuple).  At
      the one polymorphic combinator whose type variable occurs inside a
      product spine, [FOR : num # num # (num -> 'state -> unit # 'state) ->
      'state -> unit # 'state] (from [state_transformer]), the result is
      converted between [unit * ('state)] and the flat tuple.
    - [Def (f, x, e)] is [Definition f x := e]; a tuple argument
      [Def (f, TP [x; y], e)] is [Definition f '((x, y) : ...) := e]; a
      [unit] argument is [(_ : unit)].  [Close (state, e)] is [fun state => e].
    - Literals: [LW (i, n)] is [n2w i : word n]; [LN i] the [N] numeral;
      [LS s] the HOL string (a [list ascii], [hol_string_scope]).
    - Operations: HOL's word operations are written with their constant
      names ([word_add], [word_lsl], [word_extract h l x : word n],
      [word_concat x y : word n] for [x @@ y], ...); HOL infers the widths of
      [@@] and of extracts, so they are ascribed.  [Mop (Cast ty, x)] is
      HOL's [Import.pickCast]: [w2w], [w2n], [n2w], [w2i], [i2w], [v2w] (from
      a bit list, e.g. [v2w [b'31; b'30]]), [word_to_hex_string],
      [num_to_dec_string], [<enum>2num], [num2<enum>], and for a boolean
      [b] the word [v2w [b]] (or [1w]/[0w] for a literal).  [BL (n, w)] is
      the [boolify<n>] function HOL defines on demand (via
      [bitstringLib.bitify_boolify]).  [EQ (x, y)] is [bool_decide (x = y)].
    - [CS (x, cases)] (HOL [case]) is a [match] with HOL's first-match
      semantics; a missing case (HOL leaves it unspecified) is [ARB].  When
      a pattern contains a literal (a word, number or string), the cases are
      tested in order with [bool_decide] instead (as HOL's
      [TypeBase.mk_pattern_fn] does).
    - Floating point: the IEEE operations ([fp32_add], ...) are those of
      [machine_ieee], which Galette provides only as unspecified stand-ins
      (see [theories/HOL/src/floating_point/machine_ieee.v]); the
      floating-point instructions are therefore written as in HOL but say
      nothing about their results.

    The L3 declaration forms [Construct], [Record] are not recognised by
    [scripts/check-hol-refs.py] (only [val f_def = Def ...] is), so the
    datatypes carry no [HOL] tags; each says which HOL type it is.  Every
    [Def]/[Def0] below is tagged with its [_def].  The auxiliary functions
    that HOL generates outside the script (record field updates
    [t_f_fupd], enumeration maps [t2num]/[num2t], [boolify<n>]) are
    untagged Galette definitions with HOL's names.

    Not ported: [checkDelegation_def] (unused, recursive), the
    disassembler's polymorphic printing helpers ([imm], [pItype],
    [pCSRItype], [pStype], [pSBtype], [pUtype], [pUJtype], [pFItype],
    [pFStype]) and what depends on them ([instructionToString],
    [log_instruction]).  [walk64] (recursive on [level]) is defined through
    a fuelled body and HOL's equation is the theorem [walk64_def]. *)

From Galette Require Import Base.
From Galette.HOL.src.n_bit Require Import words bitstring.
From Galette.HOL.src.integer Require Import integer_word.
From Galette.HOL.src.list.src Require Import list list.extra.
From Galette.HOL.src.coretypes Require Import option.
From Galette.HOL.src.string Require Import string ASCIInumbers.
From Galette.HOL.src.combin Require Import combin.
From Galette.HOL.src.floating_point Require Import binary_ieee machine_ieee.
From Galette.HOL.src.monad.more_monads Require Import state_transformer.
Open Scope N_scope.
Local Open Scope hol_string_scope.

(** ** Datatypes *)

(** HOL datatype [rawInstType] (L3 [Construct]). *)
Inductive rawInstType : Type :=
| Half : word16 -> rawInstType
| Word : word32 -> rawInstType
.
#[global] Instance rawInstType_inhabited : Inhabited rawInstType := Half (inhabitant _).

(** HOL datatype [accessType] (L3 [Construct]). *)
Inductive accessType : Type :=
| Read : accessType
| Write : accessType
.
#[global] Instance accessType_inhabited : Inhabited accessType := Read.

