(** HOL datatype [Internal] (L3 [Construct]). Its Rocq name is [Internal_ty]: HOL also has a constructor [Internal] (of [instruction]), and Rocq types and constructors share a namespace. *)
Inductive Internal_ty : Type :=
| FETCH_FAULT : word64 -> Internal_ty
| FETCH_MISALIGNED : word64 -> Internal_ty
