(** HOL record type [riscv_state] (L3 [Record]); fields are named after HOL's
    accessor constants [riscv_state_<field>]. *)
Record riscv_state : Type := {
  riscv_state_MEM8 : word64 -> word8;
  riscv_state_c_ExitCode : word8 -> word64;
  riscv_state_c_HCSR : word8 -> HypervisorCSR;
  riscv_state_c_MCSR : word8 -> MachineCSR;
  riscv_state_c_NextFetch : word8 -> option TransferControl;
  riscv_state_c_PC : word8 -> word64;
  riscv_state_c_ReserveLoad : word8 -> option word64;
  riscv_state_c_SCSR : word8 -> SupervisorCSR;
  riscv_state_c_Skip : word8 -> word64;
  riscv_state_c_UCSR : word8 -> UserCSR;
  riscv_state_c_cycles : word8 -> word64;
  riscv_state_c_fpr : word8 -> word5 -> word64;
  riscv_state_c_gpr : word8 -> word5 -> word64;
  riscv_state_c_instret : word8 -> word64;
  riscv_state_c_tlb : word8 -> word4 -> option TLBEntry;
  riscv_state_c_update : word8 -> StateDelta;
  riscv_state_clock : word64;
  riscv_state_done : bool;
  riscv_state_exception : exception;
  riscv_state_log : list (N * string);
  riscv_state_procID : word8;
  riscv_state_totalCore : N
}.
#[global] Instance riscv_state_inhabited : Inhabited riscv_state :=
  {| riscv_state_MEM8 := inhabitant _;
     riscv_state_c_ExitCode := inhabitant _;
     riscv_state_c_HCSR := inhabitant _;
     riscv_state_c_MCSR := inhabitant _;
     riscv_state_c_NextFetch := inhabitant _;
     riscv_state_c_PC := inhabitant _;
     riscv_state_c_ReserveLoad := inhabitant _;
     riscv_state_c_SCSR := inhabitant _;
     riscv_state_c_Skip := inhabitant _;
     riscv_state_c_UCSR := inhabitant _;
     riscv_state_c_cycles := inhabitant _;
     riscv_state_c_fpr := inhabitant _;
     riscv_state_c_gpr := inhabitant _;
     riscv_state_c_instret := inhabitant _;
     riscv_state_c_tlb := inhabitant _;
     riscv_state_c_update := inhabitant _;
     riscv_state_clock := inhabitant _;
     riscv_state_done := inhabitant _;
