(** ** Enumerations as numbers (HOL [t2num], [num2t]) *)

Definition accessType2num (x : accessType) : N :=
  match x with
  | Read => 0
  | Write => 1
  end.
Definition num2accessType (n : N) : accessType :=
  if n =? 0 then Read
  else if n =? 1 then Write else ARB.

Definition fetchType2num (x : fetchType) : N :=
  match x with
  | Instruction => 0
  | Data => 1
  end.
Definition num2fetchType (n : N) : fetchType :=
  if n =? 0 then Instruction
  else if n =? 1 then Data else ARB.

Definition Architecture2num (x : Architecture) : N :=
  match x with
  | RV32I => 0
  | RV64I => 1
  | RV128I => 2
  end.
Definition num2Architecture (n : N) : Architecture :=
  if n =? 0 then RV32I
  else if n =? 1 then RV64I
  else if n =? 2 then RV128I else ARB.

Definition Privilege2num (x : Privilege) : N :=
  match x with
  | User => 0
  | Supervisor => 1
  | Hypervisor => 2
  | Machine => 3
  end.
Definition num2Privilege (n : N) : Privilege :=
  if n =? 0 then User
  else if n =? 1 then Supervisor
  else if n =? 2 then Hypervisor
  else if n =? 3 then Machine else ARB.

Definition VM_Mode2num (x : VM_Mode) : N :=
  match x with
  | Mbare => 0
  | Mbb => 1
  | Mbbid => 2
  | Sv32 => 3
  | Sv39 => 4
  | Sv48 => 5
  | Sv57 => 6
  | Sv64 => 7
  end.
Definition num2VM_Mode (n : N) : VM_Mode :=
  if n =? 0 then Mbare
  else if n =? 1 then Mbb
  else if n =? 2 then Mbbid
  else if n =? 3 then Sv32
  else if n =? 4 then Sv39
  else if n =? 5 then Sv48
  else if n =? 6 then Sv57
  else if n =? 7 then Sv64 else ARB.

Definition ExtStatus2num (x : ExtStatus) : N :=
  match x with
  | Off => 0
  | Initial => 1
  | Clean => 2
  | Dirty => 3
  end.
Definition num2ExtStatus (n : N) : ExtStatus :=
  if n =? 0 then Off
  else if n =? 1 then Initial
  else if n =? 2 then Clean
  else if n =? 3 then Dirty else ARB.

Definition Interrupt2num (x : Interrupt) : N :=
  match x with
  | Software => 0
  | Timer => 1
  end.
Definition num2Interrupt (n : N) : Interrupt :=
  if n =? 0 then Software
  else if n =? 1 then Timer else ARB.

Definition ExceptionType2num (x : ExceptionType) : N :=
  match x with
  | Fetch_Misaligned => 0
  | Fetch_Fault => 1
  | Illegal_Instr => 2
  | Breakpoint => 3
  | Load_Fault => 4
  | AMO_Misaligned => 5
  | Store_AMO_Fault => 6
  | UMode_Env_Call => 7
  | SMode_Env_Call => 8
  | HMode_Env_Call => 9
  | MMode_Env_Call => 10
  end.
Definition num2ExceptionType (n : N) : ExceptionType :=
  if n =? 0 then Fetch_Misaligned
  else if n =? 1 then Fetch_Fault
  else if n =? 2 then Illegal_Instr
  else if n =? 3 then Breakpoint
  else if n =? 4 then Load_Fault
  else if n =? 5 then AMO_Misaligned
  else if n =? 6 then Store_AMO_Fault
  else if n =? 7 then UMode_Env_Call
  else if n =? 8 then SMode_Env_Call
  else if n =? 9 then HMode_Env_Call
  else if n =? 10 then MMode_Env_Call else ARB.

Definition Rounding2num (x : Rounding) : N :=
  match x with
  | RNE => 0
  | RTZ => 1
  | RDN => 2
  | RUP => 3
  | RMM => 4
  | RDYN => 5
  end.
Definition num2Rounding (n : N) : Rounding :=
  if n =? 0 then RNE
  else if n =? 1 then RTZ
  else if n =? 2 then RDN
  else if n =? 3 then RUP
  else if n =? 4 then RMM
  else if n =? 5 then RDYN else ARB.

