(** ** [boolify<n>] (generated by HOL's [bitstringLib.bitify_boolify]):
    the bits of a word, most significant first. *)

Definition boolify5 (w : word5) : bool * bool * bool * bool * bool :=
  (word_bit 4 w, word_bit 3 w, word_bit 2 w, word_bit 1 w, word_bit 0 w).
Definition boolify8 (w : word8) : bool * bool * bool * bool * bool * bool * bool * bool :=
  (word_bit 7 w, word_bit 6 w, word_bit 5 w, word_bit 4 w, word_bit 3 w, word_bit 2 w, word_bit 1 w, word_bit 0 w).
Definition boolify12 (w : word12) : bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool :=
  (word_bit 11 w, word_bit 10 w, word_bit 9 w, word_bit 8 w, word_bit 7 w, word_bit 6 w, word_bit 5 w, word_bit 4 w, word_bit 3 w, word_bit 2 w, word_bit 1 w, word_bit 0 w).
Definition boolify16 (w : word16) : bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool :=
  (word_bit 15 w, word_bit 14 w, word_bit 13 w, word_bit 12 w, word_bit 11 w, word_bit 10 w, word_bit 9 w, word_bit 8 w, word_bit 7 w, word_bit 6 w, word_bit 5 w, word_bit 4 w, word_bit 3 w, word_bit 2 w, word_bit 1 w, word_bit 0 w).
Definition boolify32 (w : word32) : bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool * bool :=
  (word_bit 31 w, word_bit 30 w, word_bit 29 w, word_bit 28 w, word_bit 27 w, word_bit 26 w, word_bit 25 w, word_bit 24 w, word_bit 23 w, word_bit 22 w, word_bit 21 w, word_bit 20 w, word_bit 19 w, word_bit 18 w, word_bit 17 w, word_bit 16 w, word_bit 15 w, word_bit 14 w, word_bit 13 w, word_bit 12 w, word_bit 11 w, word_bit 10 w, word_bit 9 w, word_bit 8 w, word_bit 7 w, word_bit 6 w, word_bit 5 w, word_bit 4 w, word_bit 3 w, word_bit 2 w, word_bit 1 w, word_bit 0 w).

(** ** Word operations not yet in [words] (Galette infrastructure)

    HOL [word_to_hex_string] ([w2s 16 HEX]) and the computational form of
    [word_replicate] (HOL's [word_replicate_def] is [nocompute], over
    [FCP]). *)

Definition word_to_hex_string {a : N} (w : word a) : string :=
  num_to_hex_string (w2n w).

Definition word_replicate {a b : N} (n : N) (w : word a) : word b :=
  n2w (N.iter n (fun acc => acc * 2 ^ dimindex a + w2n w) 0).

(** ** The model *)

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "raise'exception_def" *)
Definition raise'exception {A : Type} `{Inhabited A} (e : exception) : riscv_state -> A * riscv_state :=
  (fun (state : riscv_state) => ((ARB : A), (if (bool_decide ((riscv_state_exception state) = NoException)) then (riscv_state_exception_fupd (fun _ => e) state)
 else state))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "ASID_SIZE_def" *)
Definition ASID_SIZE : N :=
  6.

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "PAGESIZE_BITS_def" *)
Definition PAGESIZE_BITS : N :=
  12.

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "LEVEL_BITS_def" *)
Definition LEVEL_BITS : N :=
  9.

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "BYTE_def" *)
Definition BYTE : word3 :=
  (n2w 0 : word3).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "HALFWORD_def" *)
Definition HALFWORD : word3 :=
  (n2w 1 : word3).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "WORD_def" *)
Definition WORD : word3 :=
  (n2w 3 : word3).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "DOUBLEWORD_def" *)
Definition DOUBLEWORD : word3 :=
  (n2w 7 : word3).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "archBase_def" *)
Definition archBase (a : Architecture) : word2 :=
  (match a with
 | RV32I => (n2w 0 : word2)
 | RV64I => (n2w 2 : word2)
 | RV128I => (n2w 3 : word2)
 end).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "architecture_def" *)
Definition architecture (ab : word2) : riscv_state -> Architecture * riscv_state :=
  (fun (state : riscv_state) => (if bool_decide (ab = (n2w 0 : word2)) then (RV32I, state)
 else (if bool_decide (ab = (n2w 2 : word2)) then (RV64I, state)
 else (if bool_decide (ab = (n2w 3 : word2)) then (RV128I, state)
 else ((@raise'exception Architecture _ (UNDEFINED ("Unknown architecture: " ++ (num_to_dec_string (w2n ab))))) state))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "archName_def" *)
Definition archName (a : Architecture) : string :=
  (match a with
 | RV32I => "RV32I"
 | RV64I => "RV64I"
 | RV128I => "RV128I"
 end).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "privLevel_def" *)
Definition privLevel (p : Privilege) : word2 :=
  (match p with
 | User => (n2w 0 : word2)
 | Supervisor => (n2w 1 : word2)
 | Hypervisor => (n2w 2 : word2)
 | Machine => (n2w 3 : word2)
 end).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "privilege_def" *)
Definition privilege (p : word2) : Privilege :=
  (if bool_decide (p = (n2w 0 : word2)) then User
 else (if bool_decide (p = (n2w 1 : word2)) then Supervisor
 else (if bool_decide (p = (n2w 2 : word2)) then Hypervisor
 else (if bool_decide (p = (n2w 3 : word2)) then Machine
 else ARB)))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "privName_def" *)
Definition privName (p : Privilege) : string :=
  (match p with
 | User => "U"
 | Supervisor => "S"
 | Hypervisor => "H"
 | Machine => "M"
 end).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "vmType_def" *)
Definition vmType (vm : word5) : riscv_state -> VM_Mode * riscv_state :=
  (fun (state : riscv_state) => (if bool_decide (vm = (n2w 0 : word5)) then (Mbare, state)
 else (if bool_decide (vm = (n2w 1 : word5)) then (Mbb, state)
 else (if bool_decide (vm = (n2w 2 : word5)) then (Mbbid, state)
 else (if bool_decide (vm = (n2w 8 : word5)) then (Sv32, state)
 else (if bool_decide (vm = (n2w 9 : word5)) then (Sv39, state)
 else (if bool_decide (vm = (n2w 10 : word5)) then (Sv48, state)
 else (if bool_decide (vm = (n2w 11 : word5)) then (Sv57, state)
 else (if bool_decide (vm = (n2w 12 : word5)) then (Sv64, state)
 else ((@raise'exception VM_Mode _ (UNDEFINED ("Unknown address translation mode: " ++ (num_to_dec_string (w2n vm))))) state)))))))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "isValidVM_def" *)
Definition isValidVM (vm : word5) : bool :=
  (if bool_decide (vm = (n2w 0 : word5)) then true
 else (if bool_decide (vm = (n2w 1 : word5)) then true
 else (if bool_decide (vm = (n2w 2 : word5)) then true
 else (if bool_decide (vm = (n2w 8 : word5)) then true
 else (if bool_decide (vm = (n2w 9 : word5)) then true
 else (if bool_decide (vm = (n2w 10 : word5)) then true
 else (if bool_decide (vm = (n2w 11 : word5)) then true
 else (if bool_decide (vm = (n2w 12 : word5)) then true
 else false)))))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "vmMode_def" *)
Definition vmMode (vm : VM_Mode) : word5 :=
  (match vm with
 | Mbare => (n2w 0 : word5)
 | Mbb => (n2w 1 : word5)
 | Mbbid => (n2w 2 : word5)
 | Sv32 => (n2w 8 : word5)
 | Sv39 => (n2w 9 : word5)
 | Sv48 => (n2w 10 : word5)
 | Sv57 => (n2w 11 : word5)
 | Sv64 => (n2w 12 : word5)
 end).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "vmModeName_def" *)
Definition vmModeName (vm : VM_Mode) : string :=
  (match vm with
 | Mbare => "Mbare"
 | Mbb => "Mbb"
 | Mbbid => "Mbbid"
 | Sv32 => "Sv32"
 | Sv39 => "Sv39"
 | Sv48 => "Sv48"
 | Sv57 => "Sv57"
 | Sv64 => "Sv64"
 end).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "ext_status_def" *)
Definition ext_status (e : ExtStatus) : word2 :=
  (match e with
 | Off => (n2w 0 : word2)
 | Initial => (n2w 1 : word2)
 | Clean => (n2w 2 : word2)
 | Dirty => (n2w 3 : word2)
 end).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "extStatus_def" *)
Definition extStatus (e : word2) : ExtStatus :=
  (if bool_decide (e = (n2w 0 : word2)) then Off
 else (if bool_decide (e = (n2w 1 : word2)) then Initial
 else (if bool_decide (e = (n2w 2 : word2)) then Clean
 else (if bool_decide (e = (n2w 3 : word2)) then Dirty
 else ARB)))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "extStatusName_def" *)
Definition extStatusName (e : ExtStatus) : string :=
  (match e with
 | Off => "Off"
 | Initial => "Initial"
 | Clean => "Clean"
 | Dirty => "Dirty"
 end).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "interruptIndex_def" *)
Definition interruptIndex (i : Interrupt) : word4 :=
  (match i with
 | Software => (n2w 0 : word4)
 | Timer => (n2w 1 : word4)
 end).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "excCode_def" *)
Definition excCode (e : ExceptionType) : word4 :=
  (match e with
 | Fetch_Misaligned => (n2w 0 : word4)
 | Fetch_Fault => (n2w 1 : word4)
 | Illegal_Instr => (n2w 2 : word4)
 | Breakpoint => (n2w 3 : word4)
 | Load_Fault => (n2w 5 : word4)
 | AMO_Misaligned => (n2w 6 : word4)
 | Store_AMO_Fault => (n2w 7 : word4)
 | UMode_Env_Call => (n2w 8 : word4)
 | SMode_Env_Call => (n2w 9 : word4)
 | HMode_Env_Call => (n2w 10 : word4)
 | MMode_Env_Call => (n2w 11 : word4)
 end).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "excType_def" *)
Definition excType (e : word4) : riscv_state -> ExceptionType * riscv_state :=
  (fun (state : riscv_state) => (if bool_decide (e = (n2w 0 : word4)) then (Fetch_Misaligned, state)
 else (if bool_decide (e = (n2w 1 : word4)) then (Fetch_Fault, state)
 else (if bool_decide (e = (n2w 2 : word4)) then (Illegal_Instr, state)
 else (if bool_decide (e = (n2w 3 : word4)) then (Breakpoint, state)
 else (if bool_decide (e = (n2w 5 : word4)) then (Load_Fault, state)
 else (if bool_decide (e = (n2w 6 : word4)) then (AMO_Misaligned, state)
 else (if bool_decide (e = (n2w 7 : word4)) then (Store_AMO_Fault, state)
 else (if bool_decide (e = (n2w 8 : word4)) then (UMode_Env_Call, state)
 else (if bool_decide (e = (n2w 9 : word4)) then (SMode_Env_Call, state)
 else (if bool_decide (e = (n2w 10 : word4)) then (HMode_Env_Call, state)
 else (if bool_decide (e = (n2w 11 : word4)) then (MMode_Env_Call, state)
 else ((@raise'exception ExceptionType _ (UNDEFINED ("Unknown exception: " ++ (num_to_dec_string (w2n e))))) state))))))))))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "excName_def" *)
Definition excName (e : ExceptionType) : string :=
  (match e with
 | Fetch_Misaligned => "MISALIGNED_FETCH"
 | Fetch_Fault => "FAULT_FETCH"
 | Illegal_Instr => "ILLEGAL_INSTRUCTION"
 | Breakpoint => "BREAKPOINT"
 | Load_Fault => "FAULT_LOAD"
 | AMO_Misaligned => "MISALIGNED_AMO"
 | Store_AMO_Fault => "FAULT_STORE_AMO"
 | UMode_Env_Call => "U-EnvCall"
 | SMode_Env_Call => "S-EnvCall"
 | HMode_Env_Call => "H-EnvCall"
 | MMode_Env_Call => "M-EnvCall"
 end).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "rec'mcpuid_def" *)
Definition rec'mcpuid (x : word64) : mcpuid :=
  (Build_mcpuid (word_extract 63 62 x : word2) (word_bit 8 x) (word_bit 12 x) (word_bit 18 x) (word_bit 20 x) (word_concat (word_extract 7 0 x : word8) (word_concat (word_extract 11 9 x : word3) (word_concat (word_extract 17 13 x : word5) (word_concat (word_extract 19 19 x : word1) (word_extract 61 21 x : word 41) : word 42) : word 47) : word 50) : word 58)).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "reg'mcpuid_def" *)
Definition reg'mcpuid (x : mcpuid) : word64 :=
  (match x with
 | Build_mcpuid ArchBase I M S' U mcpuid'rst => (word_concat ArchBase (word_concat (word_extract 40 0 mcpuid'rst : word 41) (word_concat (v2w [U] : word1) (word_concat (word_extract 41 41 mcpuid'rst : word1) (word_concat (v2w [S'] : word1) (word_concat (word_extract 46 42 mcpuid'rst : word5) (word_concat (v2w [M] : word1) (word_concat (word_extract 49 47 mcpuid'rst : word3) (word_concat (v2w [I] : word1) (word_extract 57 50 mcpuid'rst : word8) : word 9) : word12) : word13) : word 18) : word 19) : word20) : word21) : word 62) : word64)
 end).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "write'rec'mcpuid_def" *)
Definition write'rec'mcpuid '((_, x) : word64 * mcpuid) : word64 :=
  (reg'mcpuid x).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "write'reg'mcpuid_def" *)
Definition write'reg'mcpuid '((_, x) : mcpuid * word64) : mcpuid :=
  (rec'mcpuid x).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "rec'mimpid_def" *)
Definition rec'mimpid (x : word64) : mimpid :=
  (Build_mimpid (word_extract 63 16 x : word 48) (word_extract 15 0 x : word16)).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "reg'mimpid_def" *)
Definition reg'mimpid (x : mimpid) : word64 :=
  (match x with
 | Build_mimpid RVImpl RVSource => (word_concat RVImpl RVSource : word64)
 end).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "write'rec'mimpid_def" *)
Definition write'rec'mimpid '((_, x) : word64 * mimpid) : word64 :=
  (reg'mimpid x).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "write'reg'mimpid_def" *)
Definition write'reg'mimpid '((_, x) : mimpid * word64) : mimpid :=
  (rec'mimpid x).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "rec'mstatus_def" *)
Definition rec'mstatus (x : word64) : mstatus :=
  (Build_mstatus (word_extract 13 12 x : word2) (word_bit 0 x) (word_bit 3 x) (word_bit 6 x) (word_bit 9 x) (word_bit 16 x) (word_extract 2 1 x : word2) (word_extract 5 4 x : word2) (word_extract 8 7 x : word2) (word_extract 11 10 x : word2) (word_bit 63 x) (word_extract 15 14 x : word2) (word_extract 21 17 x : word5) (word_extract 62 22 x : word 41)).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "reg'mstatus_def" *)
Definition reg'mstatus (x : mstatus) : word64 :=
  (match x with
