 (if ((w2n id') <? (riscv_state_totalCore state))%N then (let v := ((riscv_state_c_MCSR state) id') in
 (riscv_state_c_MCSR_fupd (fun _ => (UPDATE id' (MachineCSR_mip_fupd (fun _ => (mip_MSIP_fupd (fun _ => true) (MachineCSR_mip v))) v) (riscv_state_c_MCSR state))) state))
 else state))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "rnd_mode_static_def" *)
Definition rnd_mode_static (rnd : word3) : option Rounding :=
  (if bool_decide (rnd = (n2w 0 : word3)) then (Some RNE)
 else (if bool_decide (rnd = (n2w 1 : word3)) then (Some RTZ)
 else (if bool_decide (rnd = (n2w 2 : word3)) then (Some RDN)
 else (if bool_decide (rnd = (n2w 3 : word3)) then (Some RUP)
 else (if bool_decide (rnd = (n2w 4 : word3)) then (Some RMM)
 else (if bool_decide (rnd = (n2w 7 : word3)) then (Some RDYN)
 else (None : option Rounding))))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "rnd_mode_dynamic_def" *)
Definition rnd_mode_dynamic (rnd : word3) : option Rounding :=
  (if bool_decide (rnd = (n2w 0 : word3)) then (Some RNE)
 else (if bool_decide (rnd = (n2w 1 : word3)) then (Some RTZ)
 else (if bool_decide (rnd = (n2w 2 : word3)) then (Some RDN)
 else (if bool_decide (rnd = (n2w 3 : word3)) then (Some RUP)
 else (if bool_decide (rnd = (n2w 4 : word3)) then (Some RMM)
 else (None : option Rounding)))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "l3round_def" *)
Definition l3round (rnd : Rounding) : option rounding :=
  (match rnd with
 | RNE => (Some roundTiesToEven)
 | RTZ => (Some roundTowardZero)
 | RDN => (Some roundTowardNegative)
 | RUP => (Some roundTowardPositive)
 | RMM => (None : option rounding)
 | RDYN => (None : option rounding)
 end).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "round_def" *)
Definition round (rnd : word3) : riscv_state -> option rounding :=
  (fun (state : riscv_state) => (match (rnd_mode_static rnd) with
 | Some RDYN => (match (rnd_mode_dynamic (FPCSR_FRM (fcsr state))) with
 | Some frm => (l3round frm)
 | None => (None : option rounding)
 end)
 | Some frm => (l3round frm)
 | None => (None : option rounding)
 end)).

