 | User => UMode_Env_Call
 | Supervisor => SMode_Env_Call
 | Hypervisor => HMode_Env_Call
 | Machine => MMode_Env_Call
 end)) state)).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "checkPrivInterrupt_def" *)
Definition checkPrivInterrupt (curPriv : Privilege) : riscv_state -> option (Interrupt * Privilege) * riscv_state :=
  (fun (state : riscv_state) => (let v := (MachineCSR_mip (MCSR state)) in
 (let v0 := (MachineCSR_mie (MCSR state)) in
 (match curPriv with
 | User => ((@raise'exception (option (Interrupt * Privilege)) _ (INTERNAL_ERROR "No user-level interrupts!")) state)
 | Supervisor => ((if ((mip_STIP v) && (mie_STIE v0)) then (Some (Timer, curPriv))
 else (if ((mip_SSIP v) && (mie_SSIE v0)) then (Some (Software, curPriv))
 else (None : option (Interrupt * Privilege)))), state)
 | Hypervisor => ((if ((mip_HTIP v) && (mie_HTIE v0)) then (Some (Timer, curPriv))
 else (if ((mip_HSIP v) && (mie_HSIE v0)) then (Some (Software, curPriv))
 else (None : option (Interrupt * Privilege)))), state)
 | Machine => ((if ((mip_MTIP v) && (mie_MTIE v0)) then (Some (Timer, curPriv))
 else (if ((mip_MSIP v) && (mie_MSIE v0)) then (Some (Software, curPriv))
 else (None : option (Interrupt * Privilege)))), state)
 end)))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "checkInterrupts_def" *)
Definition checkInterrupts (_ : unit) : riscv_state -> option (Interrupt * Privilege) * riscv_state :=
  (fun (state : riscv_state) => (let v := (mstatus_MIE (MachineCSR_mstatus (MCSR state))) in
 (let v0 := ((curPrivilege tt) state) in
 (match v0 with
 | User => (let '(v1, s) := ((checkPrivInterrupt Machine) state) in
 (match v1 with
 | None => (let '(v1, s) := ((checkPrivInterrupt Hypervisor) s) in
 (match v1 with
 | None => (if ((bool_decide (v0 = User)) || v) then ((checkPrivInterrupt Supervisor) s)
 else ((None : option (Interrupt * Privilege)), s))
 | i => (i, s)
 end))
 | i => (i, s)
 end))
 | Supervisor => (let '(v1, s) := ((checkPrivInterrupt Machine) state) in
 (match v1 with
 | None => (let '(v1, s) := ((checkPrivInterrupt Hypervisor) s) in
 (match v1 with
 | None => (if ((bool_decide (v0 = User)) || v) then ((checkPrivInterrupt Supervisor) s)
 else ((None : option (Interrupt * Privilege)), s))
 | i => (i, s)
 end))
 | i => (i, s)
 end))
 | Hypervisor => (let '(v0, s) := ((checkPrivInterrupt Machine) state) in
 (match v0 with
 | None => (if v then ((checkPrivInterrupt Hypervisor) s)
 else ((None : option (Interrupt * Privilege)), s))
 | i => (i, s)
 end))
 | Machine => (if v then ((checkPrivInterrupt Machine) state)
 else ((None : option (Interrupt * Privilege)), state))
 end)))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "takeTrap_def" *)
Definition takeTrap '((intr, ec, epc, badaddr, toPriv) : bool * word4 * word64 * option word64 * Privilege) : riscv_state -> riscv_state :=
  (fun (state : riscv_state) => (let '(v0, s) := (let s0 := ((write'ReserveLoad (None : option word64)) state) in
