 (let '(v0, s) := (let s0 := ((write'MCSR (MachineCSR_mstatus_fupd (fun _ => (mstatus_MMPRV_fupd (fun _ => false) (MachineCSR_mstatus v0))) v0)) s) in
 ((MCSR s0), s0)) in
 (let s := ((write'MCSR (MachineCSR_mstatus_fupd (fun _ => (pushPrivilegeStack ((MachineCSR_mstatus (MCSR s)), toPriv))) v0)) s) in
 (match toPriv with
 | User => (snd ((@raise'exception unit _ (INTERNAL_ERROR "Illegal trap to U-mode")) s))
 | Supervisor => (let v := (SCSR s) in
 (let '(v, s) := (let s0 := ((write'SCSR (SupervisorCSR_scause_fupd (fun _ => (mcause_Int_fupd (fun _ => intr) (SupervisorCSR_scause v))) v)) s) in
 ((SCSR s0), s0)) in
 (let '(v, s) := (let s0 := ((write'SCSR (SupervisorCSR_scause_fupd (fun _ => (mcause_EC_fupd (fun _ => ec) (SupervisorCSR_scause v))) v)) s) in
 ((SCSR s0), s0)) in
 (let s := ((write'SCSR (SupervisorCSR_sepc_fupd (fun _ => epc) v)) s) in
 (let '(v, s) := (let s0 := (if (IS_SOME badaddr) then ((write'SCSR (SupervisorCSR_sbadaddr_fupd (fun _ => (THE badaddr)) (SCSR s))) s)
 else s) in
 ((SCSR s0), s0)) in
 ((write'PC (SupervisorCSR_stvec v)) s))))))
 | Hypervisor => (snd ((@raise'exception unit _ (INTERNAL_ERROR "Unsupported trap to H-mode")) s))
 | Machine => (let v0 := (MCSR s) in
 (let '(v0, s) := (let s0 := ((write'MCSR (MachineCSR_mcause_fupd (fun _ => (mcause_Int_fupd (fun _ => intr) (MachineCSR_mcause v0))) v0)) s) in
 ((MCSR s0), s0)) in
 (let '(v0, s) := (let s0 := ((write'MCSR (MachineCSR_mcause_fupd (fun _ => (mcause_EC_fupd (fun _ => ec) (MachineCSR_mcause v0))) v0)) s) in
 ((MCSR s0), s0)) in
 (let s := ((write'MCSR (MachineCSR_mepc_fupd (fun _ => epc) v0)) s) in
 (let '(v0, s) := (let s0 := (if (IS_SOME badaddr) then ((write'MCSR (MachineCSR_mbadaddr_fupd (fun _ => (THE badaddr)) (MCSR s))) s)
 else s) in
