(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "checkMemPermission_def" *)
Definition checkMemPermission '((ft, ac, priv, perm) : fetchType * accessType * Privilege * word4) : riscv_state -> bool * riscv_state :=
