 else (SV_PTE_PTE_PPNi v)) (SV_Vaddr_Sv_PgOfs va) : word 50) : word64), s0, level, (isGlobal (SV_PTE_PTE_T v)), pte_addr)), s0, (if ((negb (bool_decide ((SV_PTE_PTE_R v) = (SV_PTE_PTE_R s0)))) || (negb (bool_decide ((SV_PTE_PTE_D v) = (SV_PTE_PTE_D s0))))) then ((rawWriteData (pte_addr, (reg'SV_PTE s0), 8)) s)
