 (let s1 := (c1_, c2_) in (r, (snd s1)))))))))))).

Fixpoint walk64_fuel (n : nat) : word64 * fetchType * accessType * Privilege * word64 * N -> riscv_state -> option (word64 * SV_PTE * N * bool * word64) * riscv_state :=
  match n with
  | O => fun _ => ARB
