  end.

Definition walk64 (x : word64 * fetchType * accessType * Privilege * word64 * N) : riscv_state -> option (word64 * SV_PTE * N * bool * word64) * riscv_state :=
  let '(_, _, _, _, _, level) := x in walk64_fuel (Datatypes.S (N.to_nat level)) x.

Lemma walk64_body_cong F G vAddr ft ac priv ptb level :
  (forall a b c d e, level <> 0 ->
     F (a, b, c, d, e, level - 1) = G (a, b, c, d, e, level - 1)) ->
  walk64_body F (vAddr, ft, ac, priv, ptb, level) =
  walk64_body G (vAddr, ft, ac, priv, ptb, level).
Proof.
  intros H; unfold walk64_body; apply functional_extensionality; intros state; cbv zeta.
  destruct (bool_decide (level = 0)) eqn:E; [reflexivity|].
  rewrite H; [reflexivity|]; intro Hl; subst level; cbv in E; discriminate E.
Qed.

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "walk64_def" *)
Theorem walk64_def : forall vAddr ft ac priv ptb level,
  walk64 (vAddr, ft, ac, priv, ptb, level) =
  (fun (state : riscv_state) => (let va := (rec'SV_Vaddr vAddr) in
 (let pte_addr := (word_add ptb (word_lsl (w2w (word_extract (LEVEL_BITS - 1)%N 0 (word_lsr (SV_Vaddr_Sv_VPNi va) (level * LEVEL_BITS)%N) : word 9) : word64) 3)) in
 (let v := (rec'SV_PTE ((rawReadData pte_addr) state)) in
 (if (negb (SV_PTE_PTE_V v)) then ((None : option (word64 * SV_PTE * N * bool * word64)), state)
 else (if ((bool_decide ((SV_PTE_PTE_T v) = (n2w 0 : word4))) || (bool_decide ((SV_PTE_PTE_T v) = (n2w 1 : word4)))) then (if (bool_decide (level = 0)) then ((None : option (word64 * SV_PTE * N * bool * word64)), state)
 else ((walk64 (vAddr, ft, ac, priv, (w2w (word_lsl (SV_PTE_PTE_PPNi v) PAGESIZE_BITS) : word64), (level - 1)%N)) state))
 else (let '(v0, s) := ((checkMemPermission (ft, ac, priv, (SV_PTE_PTE_T v))) state) in
 (if (negb v0) then ((None : option (word64 * SV_PTE * N * bool * word64)), s)
 else (let '(r, c1_, c2_) := (let s0 := (SV_PTE_PTE_R_fupd (fun _ => true) v) in
 (let s0 := (if (bool_decide (ac = Write)) then (SV_PTE_PTE_D_fupd (fun _ => true) s0)
 else s0) in
 ((Some ((w2w (word_concat (if (0 <? level)%N then (word_or (word_lsl (word_lsr (SV_PTE_PTE_PPNi v) (level * LEVEL_BITS)%N) (level * LEVEL_BITS)%N) (w2w (word_and (SV_Vaddr_Sv_VPNi va) (word_sub (word_lsl (n2w 1 : word 36) (level * LEVEL_BITS)%N) (n2w 1 : word 36))) : word 38))
 else (SV_PTE_PTE_PPNi v)) (SV_Vaddr_Sv_PgOfs va) : word 50) : word64), s0, level, (isGlobal (SV_PTE_PTE_T v)), pte_addr)), s0, (if ((negb (bool_decide ((SV_PTE_PTE_R v) = (SV_PTE_PTE_R s0)))) || (negb (bool_decide ((SV_PTE_PTE_D v) = (SV_PTE_PTE_D s0))))) then ((rawWriteData (pte_addr, (reg'SV_PTE s0), 8)) s)
 else s)))) in
 (let s1 := (c1_, c2_) in (r, (snd s1)))))))))))).
Proof.
  intros vAddr ft ac priv ptb level.
  transitivity (walk64_body walk64 (vAddr, ft, ac, priv, ptb, level)); [|reflexivity].
  unfold walk64 at 1; cbn [walk64_fuel].
  apply walk64_body_cong; intros a b c d e Hl.
  unfold walk64; replace (N.to_nat level) with (Datatypes.S (N.to_nat (level - 1))) by lia.
  reflexivity.
Qed.

