 (let '(r0_, r1_, r2_) := (let '(_, _, q2_, q3_, q4_) := s in (q2_, q3_, q4_)) in ((let '(p_, _, _, _, _) := s in p_), (TLBEntry_age e), r0_, r1_, r2_))) in ((let '(p_, _, _, _, _, _) := state in p_), r0_, r1_, r2_, r3_, r4_)) in
 (let '(r0_, r1_, r2_, r3_) := (let '(_, _, q2_, q3_, q4_, q5_) := s in (q2_, q3_, q4_, q5_)) in (tt, (let '(p_, _, _, _, _, _) := s in p_), i, r0_, r1_, r2_, r3_)))
 else (let '(r0_, r1_, r2_, r3_, r4_, r5_) := state in (tt, r0_, r1_, r2_, r3_, r4_, r5_)))
