 (let '(r0_, r1_, r2_, r3_) := (let s0 := (let '(_, q1_, q2_, q3_, q4_) := s0 in (q1_, q2_, q3_, q4_)) in
 (let '(r0_, r1_) := (let '(_, _, q2_, q3_) := s0 in (q2_, q3_)) in ((let '(p_, _, _, _) := s0 in p_), (UPDATE (n2w i : word4) (Some (let '(_, _, _, _, p_, _) := state in p_)) (let '(_, _, _, p_, _, _) := state in p_)), r0_, r1_))) in ((let '(p_, _, _, _, _) := s0 in p_), r0_, r1_, r2_, r3_))) in (true, r0_, r1_, r2_, r3_, r4_))
