  (let '(v, s) := (let s0 := ((write'SCSR (SupervisorCSR_scause_fupd (fun _ => (MachineCSR_mcause (MCSR state))) (SCSR state))) state) in
 ((SCSR s0), s0)) in
 (let '(v, s) := (let s0 := ((write'SCSR (SupervisorCSR_sbadaddr_fupd (fun _ => (MachineCSR_mbadaddr (MCSR s))) v)) s) in
 ((SCSR s0), s0)) in
 (let '(v, s) := (let s0 := ((write'SCSR (SupervisorCSR_sepc_fupd (fun _ => (MachineCSR_mepc (MCSR s))) v)) s) in
 ((MCSR s0), s0)) in
 ((write'NextFetch (Some Mrts)) ((write'MCSR (MachineCSR_mstatus_fupd (fun _ => (mstatus_MPRV_fupd (fun _ => (privLevel Supervisor)) (MachineCSR_mstatus v))) v)) s))))).

