(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "checkCSROp_def" *)
Definition checkCSROp '((csr, rs1, a) : word12 * word5 * accessType) : riscv_state -> bool * riscv_state :=
  (fun (state : riscv_state) => (let '(v, s) := ((is_CSR_defined csr) state) in
 ((v && (check_CSR_access ((csrRW csr), (csrPR csr), ((curPrivilege tt) s), a))), s))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "dfn'CSRRW_def" *)
Definition dfn'CSRRW '((rd, rs1, csr) : word5 * word5 * word12) : riscv_state -> riscv_state :=
  (fun (state : riscv_state) => (let '(v, s) := ((checkCSROp (csr, rs1, Write)) state) in
 (if v then (let '(v, s) := ((CSR csr) s) in
 ((write'GPR (v, rd)) ((writeCSR (csr, ((GPR rs1) s))) s)))
 else ((signalException Illegal_Instr) s)))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "dfn'CSRRS_def" *)
