 else Write))) state) in
 (if v then (let '(v, s) := ((CSR csr) s) in
 ((write'GPR (v, rd)) (if (negb (bool_decide (rs1 = (n2w 0 : word5)))) then ((writeCSR (csr, (word_or v ((GPR rs1) s)))) s)
 else s)))
 else ((signalException Illegal_Instr) s)))).

