(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "Fetch_def" *)
Definition Fetch (_ : unit) : riscv_state -> FetchResult * riscv_state :=
  (fun (state : riscv_state) => (let v := (PC state) in
 (if (word_bit 0 v) then ((F_Error (Internal (FETCH_MISALIGNED v))), state)
 else (let '(v0, s) := ((translateAddr (v, Instruction, Read)) state) in
 (match v0 with
 | Some pPC => (let '(v0, s) := ((rawReadInst pPC) s) in
 ((F_Result v0), (let '(v1, s) := (let s0 := ((write'Delta (StateDelta_exc_taken_fupd (fun _ => false) (Delta s))) s) in
 ((Delta s0), s0)) in
 (let '(v1, s) := (let s0 := ((write'Delta (StateDelta_fetch_exc_fupd (fun _ => false) v1)) s) in
 ((Delta s0), s0)) in
 (let '(v1, s) := (let s0 := ((write'Delta (StateDelta_pc_fupd (fun _ => v) v1)) s) in
 ((Delta s0), s0)) in
 (let '(v, s) := (let s0 := ((write'Delta (StateDelta_rinstr_fupd (fun _ => v0) v1)) s) in
 ((Delta s0), s0)) in
 (let '(v, s) := (let s0 := ((write'Delta (StateDelta_addr_fupd (fun _ => (None : option word64)) v)) s) in
 ((Delta s0), s0)) in
 (let '(v, s) := (let s0 := ((write'Delta (StateDelta_data1_fupd (fun _ => (None : option word64)) v)) s) in
 ((Delta s0), s0)) in
 (let '(v, s) := (let s0 := ((write'Delta (StateDelta_data2_fupd (fun _ => (None : option word64)) v)) s) in
 ((Delta s0), s0)) in
 (let '(v, s) := (let s0 := ((write'Delta (StateDelta_fp_data_fupd (fun _ => (None : option word64)) v)) s) in
 ((Delta s0), s0)) in
 ((write'Delta (StateDelta_st_width_fupd (fun _ => (None : option word32)) v)) s)))))))))))
 | None => ((F_Error (Internal (FETCH_FAULT v))), s)
 end))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "asImm12_def" *)
Definition asImm12 '((imm12, imm11, immhi, immlo) : word1 * word1 * word6 * word4) : word12 :=
  (word_concat imm12 (word_concat imm11 (word_concat immhi immlo : word 10) : word 11) : word12).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "asImm20_def" *)
Definition asImm20 '((imm20, immhi, imm11, immlo) : word1 * word8 * word1 * word 10) : word20 :=
  (word_concat imm20 (word_concat immhi (word_concat imm11 immlo : word 11) : word 19) : word20).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "asSImm12_def" *)
Definition asSImm12 '((immhi, immlo) : word7 * word5) : word12 :=
  (word_concat immhi immlo : word12).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "Decode_def" *)
Definition Decode (w : word32) : instruction :=
  (let '(b'31, b'30, b'29, b'28, b'27, b'26, b'25, b'24, b'23, b'22, b'21, b'20, b'19, b'18, b'17, b'16, b'15, b'14, b'13, b'12, b'11, b'10, b'9, b'8, b'7, b'6, b'5, b'4, b'3, b'2, b'1, b'0) := (boolify32 w) in
