 else (if ((negb b'31) && (b'30 && (b'29 && ((negb b'28) && ((negb b'27) && ((negb b'14) && (b'13 && (b'12 && (b'5 && ((negb b'4) && (b'3 && b'2))))))))))) then (AMO (AMOAND_D ((v2w [b'26] : word1), (v2w [b'25] : word1), (v2w [b'11; b'10; b'9; b'8; b'7] : word5), (v2w [b'19; b'18; b'17; b'16; b'15] : word5), (v2w [b'24; b'23; b'22; b'21; b'20] : word5))))
 else (if ((negb b'31) && (b'30 && ((negb b'29) && ((negb b'28) && ((negb b'27) && ((negb b'14) && (b'13 && (b'12 && (b'5 && ((negb b'4) && (b'3 && b'2))))))))))) then (AMO (AMOOR_D ((v2w [b'26] : word1), (v2w [b'25] : word1), (v2w [b'11; b'10; b'9; b'8; b'7] : word5), (v2w [b'19; b'18; b'17; b'16; b'15] : word5), (v2w [b'24; b'23; b'22; b'21; b'20] : word5))))
 else (if (b'31 && ((negb b'30) && ((negb b'29) && ((negb b'28) && ((negb b'27) && ((negb b'14) && (b'13 && (b'12 && (b'5 && ((negb b'4) && (b'3 && b'2))))))))))) then (AMO (AMOMIN_D ((v2w [b'26] : word1), (v2w [b'25] : word1), (v2w [b'11; b'10; b'9; b'8; b'7] : word5), (v2w [b'19; b'18; b'17; b'16; b'15] : word5), (v2w [b'24; b'23; b'22; b'21; b'20] : word5))))
 else (if (b'31 && ((negb b'30) && (b'29 && ((negb b'28) && ((negb b'27) && ((negb b'14) && (b'13 && (b'12 && (b'5 && ((negb b'4) && (b'3 && b'2))))))))))) then (AMO (AMOMAX_D ((v2w [b'26] : word1), (v2w [b'25] : word1), (v2w [b'11; b'10; b'9; b'8; b'7] : word5), (v2w [b'19; b'18; b'17; b'16; b'15] : word5), (v2w [b'24; b'23; b'22; b'21; b'20] : word5))))
 else (if (b'31 && (b'30 && ((negb b'29) && ((negb b'28) && ((negb b'27) && ((negb b'14) && (b'13 && (b'12 && (b'5 && ((negb b'4) && (b'3 && b'2))))))))))) then (AMO (AMOMINU_D ((v2w [b'26] : word1), (v2w [b'25] : word1), (v2w [b'11; b'10; b'9; b'8; b'7] : word5), (v2w [b'19; b'18; b'17; b'16; b'15] : word5), (v2w [b'24; b'23; b'22; b'21; b'20] : word5))))
 else (if (b'31 && (b'30 && (b'29 && ((negb b'28) && ((negb b'27) && ((negb b'14) && (b'13 && (b'12 && (b'5 && ((negb b'4) && (b'3 && b'2))))))))))) then (AMO (AMOMAXU_D ((v2w [b'26] : word1), (v2w [b'25] : word1), (v2w [b'11; b'10; b'9; b'8; b'7] : word5), (v2w [b'19; b'18; b'17; b'16; b'15] : word5), (v2w [b'24; b'23; b'22; b'21; b'20] : word5))))
 else UnknownInstruction))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))))
 else UnknownInstruction))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "instr_def" *)
Definition instr (o : string) : string :=
  (PAD_RIGHT " "%char 12 o).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "amotype_def" *)
Definition amotype '((aq, rl) : word1 * word1) : string :=
  (let sc1_ := (aq, rl) in (let '(l2_, l3_) := sc1_ in if (bool_decide (l2_ = (n2w 0 : word1)) && bool_decide (l3_ = (n2w 0 : word1))) then ""
 else (let '(l4_, l5_) := sc1_ in if (bool_decide (l4_ = (n2w 1 : word1)) && bool_decide (l5_ = (n2w 0 : word1))) then ".aq"
 else (let '(l6_, l7_) := sc1_ in if (bool_decide (l6_ = (n2w 0 : word1)) && bool_decide (l7_ = (n2w 1 : word1))) then ".rl"
 else (let '(l8_, l9_) := sc1_ in if (bool_decide (l8_ = (n2w 1 : word1)) && bool_decide (l9_ = (n2w 1 : word1))) then ".sc"
 else ARB))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "pRtype_def" *)
Definition pRtype '((o, rd, rs1, rs2) : string * word5 * word5 * word5) : string :=
  ((instr o) ++ (" " ++ ((reg rd) ++ (", " ++ ((reg rs1) ++ (", " ++ (reg rs2))))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "pARtype_def" *)
Definition pARtype '((o, aq, rl, rd, rs1, rs2) : string * word1 * word1 * word5 * word5 * word5) : string :=
  (pRtype ((o ++ (amotype (aq, rl))), rd, rs1, rs2)).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "pLRtype_def" *)
Definition pLRtype '((o, aq, rl, rd, rs1) : string * word1 * word1 * word5 * word5) : string :=
  ((instr (o ++ (amotype (aq, rl)))) ++ (" " ++ ((reg rd) ++ (", " ++ (reg rs1))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "pCSRtype_def" *)
Definition pCSRtype '((o, rd, rs1, csr) : string * word5 * word5 * word12) : string :=
  ((instr o) ++ (" " ++ ((reg rd) ++ (", " ++ ((reg rs1) ++ (", " ++ (csrName csr))))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "pN0type_def" *)
Definition pN0type (o : string) : string :=
  (instr o).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "pN1type_def" *)
Definition pN1type '((o, r) : string * word5) : string :=
  ((instr o) ++ (" " ++ (reg r))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "pFRtype_def" *)
Definition pFRtype '((o, rd, rs1, rs2) : string * word5 * word5 * word5) : string :=
  ((instr o) ++ (" " ++ ((fpreg rd) ++ (", " ++ ((fpreg rs1) ++ (", " ++ (fpreg rs2))))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "pFR1type_def" *)
Definition pFR1type '((o, rd, rs) : string * word5 * word5) : string :=
  ((instr o) ++ (" " ++ ((fpreg rd) ++ (", " ++ (fpreg rs))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "pFR3type_def" *)
Definition pFR3type '((o, rd, rs1, rs2, rs3) : string * word5 * word5 * word5 * word5) : string :=
  ((instr o) ++ (" " ++ ((fpreg rd) ++ (", " ++ ((fpreg rs1) ++ (", " ++ ((fpreg rs2) ++ (", " ++ (fpreg rs3))))))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "pCFItype_def" *)
Definition pCFItype '((o, rd, rs) : string * word5 * word5) : string :=
  ((instr o) ++ (" " ++ ((fpreg rd) ++ (", " ++ (reg rs))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "pCIFtype_def" *)
Definition pCIFtype '((o, rd, rs) : string * word5 * word5) : string :=
  ((instr o) ++ (" " ++ ((reg rd) ++ (", " ++ (fpreg rs))))).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "Rtype_def" *)
Definition Rtype '((o, f3, rd, rs1, rs2, f7) : word7 * word3 * word5 * word5 * word5 * word7) : word32 :=
  (word_concat f7 (word_concat rs2 (word_concat rs1 (word_concat f3 (word_concat rd o : word12) : word 15) : word20) : word 25) : word32).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "R4type_def" *)
Definition R4type '((o, f3, rd, rs1, rs2, rs3, f2) : word7 * word3 * word5 * word5 * word5 * word5 * word2) : word32 :=
  (word_concat rs3 (word_concat f2 (word_concat rs2 (word_concat rs1 (word_concat f3 (word_concat rd o : word12) : word 15) : word20) : word 25) : word 27) : word32).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "Itype_def" *)
Definition Itype '((o, f3, rd, rs1, imm') : word7 * word3 * word5 * word5 * word12) : word32 :=
  (word_concat imm' (word_concat rs1 (word_concat f3 (word_concat rd o : word12) : word 15) : word20) : word32).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "Stype_def" *)
Definition Stype '((o, f3, rs1, rs2, imm') : word7 * word3 * word5 * word5 * word12) : word32 :=
  (word_concat (word_extract 11 5 imm' : word7) (word_concat rs2 (word_concat rs1 (word_concat f3 (word_concat (word_extract 4 0 imm' : word5) o : word12) : word 15) : word20) : word 25) : word32).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "SBtype_def" *)
Definition SBtype '((o, f3, rs1, rs2, imm') : word7 * word3 * word5 * word5 * word12) : word32 :=
  (word_concat (v2w [(word_bit 11 imm')] : word1) (word_concat (word_extract 9 4 imm' : word6) (word_concat rs2 (word_concat rs1 (word_concat f3 (word_concat (word_extract 3 0 imm' : word4) (word_concat (v2w [(word_bit 10 imm')] : word1) o : word8) : word12) : word 15) : word20) : word 25) : word 31) : word32).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "Utype_def" *)
Definition Utype '((o, rd, imm') : word7 * word5 * word20) : word32 :=
  (word_concat imm' (word_concat rd o : word12) : word32).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "UJtype_def" *)
Definition UJtype '((o, rd, imm') : word7 * word5 * word20) : word32 :=
  (word_concat (v2w [(word_bit 19 imm')] : word1) (word_concat (word_extract 9 0 imm' : word 10) (word_concat (v2w [(word_bit 10 imm')] : word1) (word_concat (word_extract 18 11 imm' : word8) (word_concat rd o : word12) : word20) : word21) : word 31) : word32).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "opc_def" *)
Definition opc (code : word8) : word7 :=
  (word_concat (word_extract 4 0 code : word5) (n2w 3 : word2) : word7).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "amofunc_def" *)
Definition amofunc '((code, aq, rl) : word5 * word1 * word1) : word7 :=
  (word_concat code (word_concat aq rl : word2) : word7).

(*! HOL "HOL/examples/l3-machine-code/riscv/model/riscvScript.sml" "Encode_def" *)
Definition Encode (i : instruction) : word32 :=
  (match i with
 | Branch (BEQ (rs1, rs2, imm')) => (SBtype ((opc (n2w 24 : word8)), (n2w 0 : word3), rs1, rs2, imm'))
 | Branch (BNE (rs1, rs2, imm')) => (SBtype ((opc (n2w 24 : word8)), (n2w 1 : word3), rs1, rs2, imm'))
 | Branch (BLT (rs1, rs2, imm')) => (SBtype ((opc (n2w 24 : word8)), (n2w 4 : word3), rs1, rs2, imm'))
 | Branch (BGE (rs1, rs2, imm')) => (SBtype ((opc (n2w 24 : word8)), (n2w 5 : word3), rs1, rs2, imm'))
 | Branch (BLTU (rs1, rs2, imm')) => (SBtype ((opc (n2w 24 : word8)), (n2w 6 : word3), rs1, rs2, imm'))
 | Branch (BGEU (rs1, rs2, imm')) => (SBtype ((opc (n2w 24 : word8)), (n2w 7 : word3), rs1, rs2, imm'))
 | Branch (JALR (rd, rs1, imm')) => (Itype ((opc (n2w 25 : word8)), (n2w 0 : word3), rd, rs1, imm'))
 | Branch (JAL (rd, imm')) => (UJtype ((opc (n2w 27 : word8)), rd, imm'))
 | ArithI (LUI (rd, imm')) => (Utype ((opc (n2w 13 : word8)), rd, imm'))
 | ArithI (AUIPC (rd, imm')) => (Utype ((opc (n2w 5 : word8)), rd, imm'))
 | ArithI (ADDI (rd, rs1, imm')) => (Itype ((opc (n2w 4 : word8)), (n2w 0 : word3), rd, rs1, imm'))
 | Shift (SLLI (rd, rs1, imm')) => (Itype ((opc (n2w 4 : word8)), (n2w 1 : word3), rd, rs1, (word_concat (n2w 0 : word6) imm' : word12)))
 | ArithI (SLTI (rd, rs1, imm')) => (Itype ((opc (n2w 4 : word8)), (n2w 2 : word3), rd, rs1, imm'))
 | ArithI (SLTIU (rd, rs1, imm')) => (Itype ((opc (n2w 4 : word8)), (n2w 3 : word3), rd, rs1, imm'))
 | ArithI (XORI (rd, rs1, imm')) => (Itype ((opc (n2w 4 : word8)), (n2w 4 : word3), rd, rs1, imm'))
 | Shift (SRLI (rd, rs1, imm')) => (Itype ((opc (n2w 4 : word8)), (n2w 5 : word3), rd, rs1, (word_concat (n2w 0 : word6) imm' : word12)))
 | Shift (SRAI (rd, rs1, imm')) => (Itype ((opc (n2w 4 : word8)), (n2w 5 : word3), rd, rs1, (word_concat (n2w 16 : word6) imm' : word12)))
 | ArithI (ORI (rd, rs1, imm')) => (Itype ((opc (n2w 4 : word8)), (n2w 6 : word3), rd, rs1, imm'))
 | ArithI (ANDI (rd, rs1, imm')) => (Itype ((opc (n2w 4 : word8)), (n2w 7 : word3), rd, rs1, imm'))
 | ArithR (ADD (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 0 : word3), rd, rs1, rs2, (n2w 0 : word7)))
 | ArithR (SUB (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 0 : word3), rd, rs1, rs2, (n2w 32 : word7)))
 | Shift (SLL (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 1 : word3), rd, rs1, rs2, (n2w 0 : word7)))
 | ArithR (SLT (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 2 : word3), rd, rs1, rs2, (n2w 0 : word7)))
 | ArithR (SLTU (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 3 : word3), rd, rs1, rs2, (n2w 0 : word7)))
 | ArithR (XOR (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 4 : word3), rd, rs1, rs2, (n2w 0 : word7)))
 | Shift (SRL (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 5 : word3), rd, rs1, rs2, (n2w 0 : word7)))
 | Shift (SRA (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 5 : word3), rd, rs1, rs2, (n2w 32 : word7)))
 | ArithR (OR (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 6 : word3), rd, rs1, rs2, (n2w 0 : word7)))
 | ArithR (AND (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 7 : word3), rd, rs1, rs2, (n2w 0 : word7)))
 | ArithI (ADDIW (rd, rs1, imm')) => (Itype ((opc (n2w 6 : word8)), (n2w 0 : word3), rd, rs1, imm'))
 | Shift (SLLIW (rd, rs1, imm')) => (Itype ((opc (n2w 6 : word8)), (n2w 1 : word3), rd, rs1, (word_concat (n2w 0 : word7) imm' : word12)))
 | Shift (SRLIW (rd, rs1, imm')) => (Itype ((opc (n2w 6 : word8)), (n2w 5 : word3), rd, rs1, (word_concat (n2w 0 : word7) imm' : word12)))
 | Shift (SRAIW (rd, rs1, imm')) => (Itype ((opc (n2w 6 : word8)), (n2w 5 : word3), rd, rs1, (word_concat (n2w 32 : word7) imm' : word12)))
 | ArithR (ADDW (rd, rs1, rs2)) => (Rtype ((opc (n2w 14 : word8)), (n2w 0 : word3), rd, rs1, rs2, (n2w 0 : word7)))
 | ArithR (SUBW (rd, rs1, rs2)) => (Rtype ((opc (n2w 14 : word8)), (n2w 0 : word3), rd, rs1, rs2, (n2w 32 : word7)))
 | Shift (SLLW (rd, rs1, rs2)) => (Rtype ((opc (n2w 14 : word8)), (n2w 1 : word3), rd, rs1, rs2, (n2w 0 : word7)))
 | Shift (SRLW (rd, rs1, rs2)) => (Rtype ((opc (n2w 14 : word8)), (n2w 5 : word3), rd, rs1, rs2, (n2w 0 : word7)))
 | Shift (SRAW (rd, rs1, rs2)) => (Rtype ((opc (n2w 14 : word8)), (n2w 5 : word3), rd, rs1, rs2, (n2w 32 : word7)))
 | MulDiv (MUL (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 0 : word3), rd, rs1, rs2, (n2w 1 : word7)))
 | MulDiv (MULH (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 1 : word3), rd, rs1, rs2, (n2w 1 : word7)))
 | MulDiv (MULHSU (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 2 : word3), rd, rs1, rs2, (n2w 1 : word7)))
 | MulDiv (MULHU (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 3 : word3), rd, rs1, rs2, (n2w 1 : word7)))
 | MulDiv (DIV (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 4 : word3), rd, rs1, rs2, (n2w 1 : word7)))
 | MulDiv (DIVU (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 5 : word3), rd, rs1, rs2, (n2w 1 : word7)))
 | MulDiv (REM (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 6 : word3), rd, rs1, rs2, (n2w 1 : word7)))
 | MulDiv (REMU (rd, rs1, rs2)) => (Rtype ((opc (n2w 12 : word8)), (n2w 7 : word3), rd, rs1, rs2, (n2w 1 : word7)))
 | MulDiv (MULW (rd, rs1, rs2)) => (Rtype ((opc (n2w 14 : word8)), (n2w 0 : word3), rd, rs1, rs2, (n2w 1 : word7)))
 | MulDiv (DIVW (rd, rs1, rs2)) => (Rtype ((opc (n2w 14 : word8)), (n2w 4 : word3), rd, rs1, rs2, (n2w 1 : word7)))
 | MulDiv (DIVUW (rd, rs1, rs2)) => (Rtype ((opc (n2w 14 : word8)), (n2w 5 : word3), rd, rs1, rs2, (n2w 1 : word7)))
 | MulDiv (REMW (rd, rs1, rs2)) => (Rtype ((opc (n2w 14 : word8)), (n2w 6 : word3), rd, rs1, rs2, (n2w 1 : word7)))
 | MulDiv (REMUW (rd, rs1, rs2)) => (Rtype ((opc (n2w 14 : word8)), (n2w 7 : word3), rd, rs1, rs2, (n2w 1 : word7)))
 | Load (LB (rd, rs1, imm')) => (Itype ((opc (n2w 0 : word8)), (n2w 0 : word3), rd, rs1, imm'))
 | Load (LH (rd, rs1, imm')) => (Itype ((opc (n2w 0 : word8)), (n2w 1 : word3), rd, rs1, imm'))
 | Load (LW (rd, rs1, imm')) => (Itype ((opc (n2w 0 : word8)), (n2w 2 : word3), rd, rs1, imm'))
 | Load (LD (rd, rs1, imm')) => (Itype ((opc (n2w 0 : word8)), (n2w 3 : word3), rd, rs1, imm'))
 | Load (LBU (rd, rs1, imm')) => (Itype ((opc (n2w 0 : word8)), (n2w 4 : word3), rd, rs1, imm'))
 | Load (LHU (rd, rs1, imm')) => (Itype ((opc (n2w 0 : word8)), (n2w 5 : word3), rd, rs1, imm'))
 | Load (LWU (rd, rs1, imm')) => (Itype ((opc (n2w 0 : word8)), (n2w 6 : word3), rd, rs1, imm'))
 | Store (SB (rs1, rs2, imm')) => (Stype ((opc (n2w 8 : word8)), (n2w 0 : word3), rs1, rs2, imm'))
 | Store (SH (rs1, rs2, imm')) => (Stype ((opc (n2w 8 : word8)), (n2w 1 : word3), rs1, rs2, imm'))
 | Store (SW (rs1, rs2, imm')) => (Stype ((opc (n2w 8 : word8)), (n2w 2 : word3), rs1, rs2, imm'))
 | Store (SD (rs1, rs2, imm')) => (Stype ((opc (n2w 8 : word8)), (n2w 3 : word3), rs1, rs2, imm'))
 | FENCE (rd, rs1, pred, succ) => (Itype ((opc (n2w 3 : word8)), (n2w 0 : word3), rd, rs1, (word_concat (n2w 0 : word4) (word_concat pred succ : word8) : word12)))
 | FENCE_I (rd, rs1, imm') => (Itype ((opc (n2w 3 : word8)), (n2w 1 : word3), rd, rs1, imm'))
 | FArith (FADD_S (rd, rs1, rs2, frm)) => (Rtype ((opc (n2w 20 : word8)), frm, rd, rs1, rs2, (n2w 0 : word7)))
 | FArith (FSUB_S (rd, rs1, rs2, frm)) => (Rtype ((opc (n2w 20 : word8)), frm, rd, rs1, rs2, (n2w 4 : word7)))
